"""Anchor still images generated by local ComfyUI image workflows (F03 T2I, F04 edit).

An anchor = one immutable job directory ``<runs_root>/<job_id[:16]>/`` with the
patched graph, ``job.json`` and exactly one downloaded image. It reuses the
bridge's crash-safe executor (``bridge.advance_job``): client-chosen prompt ID
persisted before ``POST /prompt``, reconciliation on resume, ``.part`` downloads,
shared GPU gate. Only the planning and the image verification are anchor-specific.

Methods:
- ``text_to_image``: profile capability ``text_to_image``; the storyboard's first anchor.
- ``reference_edit``: profile capability ``reference_edit``; the parent anchor's exact
  bytes are uploaded and bound to ``reference_image``.
- ``independent_t2i``: explicit fallback on a T2I profile for a later anchor; recorded
  as such and never presented as a reference edit.
"""
from __future__ import annotations

import json
from dataclasses import dataclass
from pathlib import Path
from typing import Any, Literal

from pydantic import BaseModel, ConfigDict, Field, model_validator

from . import __version__
from .bridge import (
    BridgeError,
    BridgeJob,
    MODEL_INPUTS,
    _now,
    advance_job,
    load_job,
    upload_name_for,
)
from .cache import cache_key, sha256_file
from .comfy_client import ComfyClient
from .geometry import compare_images
from .media import ImageInvalid, ProbeUnavailable, inspect_image
from .workflow_adapter import (
    BindingProfile,
    WorkflowBindingError,
    graph_sha256,
    load_api_workflow,
    load_binding_profile,
    patch_workflow,
    profile_bindings,
    resolve_workflow_path,
    validate_profile,
)

Method = Literal["text_to_image", "reference_edit", "independent_t2i"]
CAPABILITY_FOR_METHOD = {"text_to_image": "text_to_image", "independent_t2i": "text_to_image",
                         "reference_edit": "reference_edit"}
PREFIX_PLACEHOLDER = "morphcurrent/__job__/anchor"


class AnchorError(BridgeError):
    pass


class AnchorRequest(BaseModel):
    """Semantic inputs of one anchor image. The seed is always explicit."""
    model_config = ConfigDict(extra="forbid")
    profile: str
    method: Method = "text_to_image"
    positive_prompt: str = Field(min_length=1)
    negative_prompt: str | None = None
    seed: int = Field(ge=0)
    width: int | None = None
    height: int | None = None
    reference_image: str | None = None
    label: str | None = None

    @model_validator(mode="after")
    def check_reference(self) -> "AnchorRequest":
        if self.method == "reference_edit" and not self.reference_image:
            raise ValueError("reference_edit requires reference_image (the parent anchor)")
        if self.method != "reference_edit" and self.reference_image:
            raise ValueError(f"{self.method} must not have a reference_image")
        return self


@dataclass
class AnchorPlan:
    request: AnchorRequest
    profile: BindingProfile
    base_graph: dict
    graph: dict
    job_id: str
    image_paths: dict[str, Path]
    image_sha256: dict[str, str]
    upload_names: dict[str, str]
    values: dict[str, Any]
    models: dict[str, str]


def plan_anchor(request: AnchorRequest, object_info: dict | None = None,
                repo_root: str | Path | None = None) -> AnchorPlan:
    """Resolve, patch and hash an anchor job without touching ComfyUI."""
    root = Path(repo_root) if repo_root else Path.cwd()
    profile_path = Path(request.profile)
    if not profile_path.is_absolute():
        profile_path = root / profile_path
    profile = load_binding_profile(profile_path)
    wanted = CAPABILITY_FOR_METHOD[request.method]
    if profile.capability != wanted:
        raise WorkflowBindingError(f"method {request.method} needs a {wanted} profile; "
                                   f"{profile.profile} declares {profile.capability}")
    base_graph = load_api_workflow(resolve_workflow_path(profile, profile_path, root))
    pre = validate_profile(profile, base_graph)
    if not pre.ok:
        raise WorkflowBindingError("; ".join(pre.errors))
    bindings = profile_bindings(profile)

    paths: dict[str, Path] = {}
    digests: dict[str, str] = {}
    names: dict[str, str] = {}
    if request.reference_image:
        path = Path(request.reference_image)
        if not path.is_absolute():
            path = root / path
        if not path.is_file():
            raise FileNotFoundError(f"reference_image: {path}")
        try:
            inspect_image(path)
        except ImageInvalid as exc:
            raise AnchorError(f"reference image {path.name} is invalid: {exc}") from exc
        paths["reference_image"] = path
        digests["reference_image"] = sha256_file(path)
        names["reference_image"] = upload_name_for(path, digests["reference_image"])

    scalar: dict[str, Any] = {"seed": request.seed, "positive_prompt": request.positive_prompt}
    for role in ("negative_prompt", "width", "height"):
        value = getattr(request, role)
        if value is None:
            continue
        if role not in bindings:
            raise WorkflowBindingError(f"{role} given but profile {profile.profile} does not bind it")
        scalar[role] = value
    if "filename_prefix" in bindings:
        scalar["filename_prefix"] = PREFIX_PLACEHOLDER
    graph = patch_workflow(base_graph, bindings, scalar, object_info)
    graph = patch_workflow(graph, bindings, names)

    models = {f"{node_id}.{key}": value for node_id, node in sorted(graph.items())
              for key, value in node["inputs"].items()
              if key in MODEL_INPUTS and isinstance(value, str)}
    job_id = cache_key(
        task={"kind": "anchor_image", "method": request.method, "profile": profile.profile,
              "graph_sha256": graph_sha256(graph)},
        dependencies=dict(digests),
        workflow_sha256=profile.workflow_sha256,
        model_sha256={},  # checkpoint hashes NOT RECORDED (F07); filenames are in the graph
        code_revision=__version__,
    )
    if "filename_prefix" in bindings:
        graph = patch_workflow(graph, bindings, {"filename_prefix": f"morphcurrent/{job_id[:16]}/anchor"})
    values = {role: graph[b["node_id"]]["inputs"][b["input"]] for role, b in bindings.items()}
    return AnchorPlan(request=request, profile=profile, base_graph=base_graph, graph=graph,
                      job_id=job_id, image_paths=paths, image_sha256=digests,
                      upload_names=names, values=values, models=models)


def open_anchor_job(plan: AnchorPlan, runs_root: str | Path) -> BridgeJob:
    job_dir = Path(runs_root) / plan.job_id[:16]
    workflow_file = job_dir / "workflow.api.json"
    if (job_dir / "job.json").exists():
        job = load_job(job_dir)
        if job.record.get("job_id") != plan.job_id:
            raise AnchorError(f"{job_dir} belongs to job {job.record.get('job_id')}, not {plan.job_id}")
        if graph_sha256(load_api_workflow(workflow_file)) != graph_sha256(plan.graph):
            raise AnchorError(f"{workflow_file} no longer matches the planned graph")
        return job
    job_dir.mkdir(parents=True, exist_ok=False)
    with workflow_file.open("x", encoding="utf-8", newline="\n") as stream:
        stream.write(json.dumps(plan.graph, indent=2, ensure_ascii=False) + "\n")
    parent = plan.image_sha256.get("reference_image")
    record = {
        "schema": 1,
        "job_id": plan.job_id,
        "kind": "anchor_image",
        "method": plan.request.method,
        "label": plan.request.label,
        "morphcurrent_version": __version__,
        "created_at": _now(),
        "state": "planned",
        "request": plan.request.model_dump(),
        "profile": plan.profile.profile,
        "capability": plan.profile.capability,
        "workflow": plan.profile.workflow,
        "workflow_sha256": plan.profile.workflow_sha256,
        "patched_graph_sha256": graph_sha256(plan.graph),
        "inputs": {role: {"path": str(plan.image_paths[role]), "sha256": plan.image_sha256[role],
                          "upload_name": plan.upload_names[role]} for role in plan.upload_names},
        "parent": {"sha256": parent} if parent else None,
        "values": plan.values,
        "models": plan.models,
        "model_sha256": "NOT RECORDED",
        "prompt_id": None,
        "comfyui": {},
        "outputs": [],
        "image": None,
        "verification": None,
        "error": None,
        "events": [{"t": _now(), "event": "planned"}],
    }
    job = BridgeJob(job_dir, record)
    job.save()
    return job


def verify_anchor_image(job: BridgeJob) -> None:
    """Exactly one structurally valid image, matching bound width/height when present."""
    images = [o for o in job.record["outputs"] if o.get("kind") == "image"]
    if len(images) != 1:
        raise job.fail(f"expected exactly one output image, got {len(images)}")
    output = images[0]
    try:
        measured = inspect_image(job.dir / output["local_path"])
    except ImageInvalid as exc:
        raise job.fail(f"output image invalid: {exc}")
    values = job.record["values"]
    mismatches = {key: {"expected": values[key], "measured": measured[key]}
                  for key in ("width", "height")
                  if isinstance(values.get(key), int) and values[key] != measured[key]}
    job.record["image"] = {"local_path": output["local_path"], "sha256": output["sha256"],
                           "bytes": output["bytes"], **measured}
    job.record["verification"] = {"status": "pass" if not mismatches else "mismatch",
                                  "measured": measured, "mismatches": mismatches}
    if mismatches:
        raise job.fail("image dimensions differ from the request", mismatches=mismatches)
    job.transition("verified", image_sha256=output["sha256"])


def run_anchor(plan: AnchorPlan, client: ComfyClient, runs_root: str | Path, *,
               submit: bool = False, retry: bool = False, allow_busy_queue: bool = False,
               timeout: float = 3600, poll_seconds: float = 2) -> BridgeJob:
    """Advance an anchor job as far as allowed (validated without ``submit``)."""
    job = open_anchor_job(plan, runs_root)
    return advance_job(job, plan, client, submit=submit, retry=retry,
                       allow_busy_queue=allow_busy_queue, timeout=timeout,
                       poll_seconds=poll_seconds, verify=verify_anchor_image)


def anchor_image_path(job: BridgeJob) -> Path:
    """Path of a verified anchor's image; refuses unverified or tampered files."""
    if job.state != "verified" or not job.record.get("image"):
        raise AnchorError(f"anchor {job.record['job_id'][:16]} is {job.state}, not verified")
    path = job.dir / job.record["image"]["local_path"]
    if sha256_file(path) != job.record["image"]["sha256"]:
        raise AnchorError(f"{path} no longer matches its recorded SHA-256")
    return path


@dataclass(frozen=True)
class AnchorSpec:
    """One storyboard anchor as the chain needs it (F04/F05)."""
    id: str
    method: Method
    prompt: str
    seed: int
    negative_prompt: str | None = None
    reference: str | None = None  # parent id: edited for reference_edit, continuity-only otherwise


@dataclass
class ChainResult:
    jobs: dict[str, BridgeJob]
    blocked: dict[str, str]
    stopped_at: str | None = None

    @property
    def complete(self) -> bool:
        return not self.blocked and all(j.state == "verified" for j in self.jobs.values()) \
            and self.stopped_at is None


def run_anchor_chain(specs: list[AnchorSpec], *, client: ComfyClient, runs_root: str | Path,
                     t2i_profile: str | None, edit_profile: str | None,
                     width: int | None = None, height: int | None = None,
                     submit: bool = False, retry: bool = False, allow_busy_queue: bool = False,
                     repo_root: str | Path | None = None, timeout: float = 1800,
                     poll_seconds: float = 2, budget=None) -> ChainResult:
    """Generate anchors in storyboard order, one GPU job at a time.

    A ``reference_edit`` child is planned only once its parent is verified, from
    the parent's exact verified file (SHA re-checked), so the shared anchor of two
    bridges is byte-identical. A missing edit profile BLOCKS the anchor; it is
    never silently generated by text-to-image instead.
    """
    result = ChainResult(jobs={}, blocked={})
    object_info = client.object_info()
    for spec in specs:
        profile = edit_profile if spec.method == "reference_edit" else t2i_profile
        if profile is None:
            needed = "reference_edit" if spec.method == "reference_edit" else "text_to_image"
            hint = (" To use text-to-image instead, the storyboard must say "
                    "`generation: independent_t2i` explicitly (it is labelled and needs human review)."
                    if spec.method == "reference_edit" else "")
            result.blocked[spec.id] = f"BLOCKED: no verified {needed} binding profile.{hint}"
            continue
        reference_image = None
        if spec.method == "reference_edit":
            parent = result.jobs.get(spec.reference or "")
            if parent is None or parent.state != "verified":
                result.blocked[spec.id] = f"BLOCKED: parent {spec.reference!r} is not a verified anchor yet"
                continue
            reference_image = str(anchor_image_path(parent))
        # Size is patched only where the graph exposes it (edit graphs usually follow the
        # reference); continuity is then enforced on the verified output below.
        profile_path = Path(profile) if Path(profile).is_absolute() else Path(repo_root or ".") / profile
        bound = load_binding_profile(profile_path).bindings
        request = AnchorRequest(profile=profile, method=spec.method, positive_prompt=spec.prompt,
                                negative_prompt=spec.negative_prompt,  # unbound -> plan refuses (no silent drop)
                                seed=spec.seed,
                                width=width if "width" in bound else None,
                                height=height if "height" in bound else None,
                                reference_image=reference_image, label=spec.id)
        plan = plan_anchor(request, object_info, repo_root=repo_root)
        if (submit and budget is not None and not job_is_verified(runs_root, plan.job_id)
                and not budget.allow("anchor", {"id": f"anchor:{spec.id}"})):
            result.stopped_at = spec.id  # F17: budget reached before a new GPU submission
            break
        job = run_anchor(plan, client, runs_root, submit=submit, retry=retry,
                         allow_busy_queue=allow_busy_queue, timeout=timeout, poll_seconds=poll_seconds)
        result.jobs[spec.id] = job
        if job.state == "verified" and spec.reference and spec.reference in result.jobs:
            _check_continuity(job, result.jobs[spec.reference], spec)
        if job.state != "verified":
            result.stopped_at = spec.id  # later anchors depend on this one's bytes
            if submit:
                break
    return result


def _check_continuity(child: BridgeJob, parent: BridgeJob, spec: AnchorSpec) -> None:
    c, p = child.record["image"], parent.record["image"]
    review = "required" if spec.method == "independent_t2i" else "recommended"
    child.record["continuity"] = {"parent": spec.reference, "parent_sha256": p["sha256"],
                                  "conditioned_on_parent": spec.method == "reference_edit",
                                  "review": review}
    try:  # F12: advisory framing/scale/viewpoint heuristics, recorded for the reviewer
        geometry = compare_images(parent.dir / p["local_path"], child.dir / c["local_path"])
        child.record["continuity"]["geometry"] = geometry["comparison"]
        if geometry["comparison"]["flags"]:
            child.record["continuity"]["review"] = "required"
    except (ProbeUnavailable, RuntimeError) as exc:
        child.record["continuity"]["geometry"] = {"status": f"unavailable: {exc}"}
    child.save()
    if (c["width"], c["height"]) != (p["width"], p["height"]):
        raise child.fail(f"anchor {spec.id} is {c['width']}x{c['height']} but parent {spec.reference} is "
                         f"{p['width']}x{p['height']}; both endpoints of a bridge must match")


def job_is_verified(runs_root: str | Path, job_id: str) -> bool:
    """True when a content-addressed job already finished (no GPU needed to 'run' it)."""
    record = Path(runs_root) / job_id[:16] / "job.json"
    try:
        return json.loads(record.read_text(encoding="utf-8")).get("state") == "verified"
    except (OSError, ValueError):
        return False


def request_from_anchor_job(job_dir: str | Path) -> AnchorRequest:
    return AnchorRequest.model_validate(load_job(job_dir).record["request"])
